from itertools import combinations

def subsets(n):
    base = range(n)
    for r in range(n + 1):
        for c in combinations(base, r):
            yield frozenset(c)

def search(n, prem, concl):
    # Exhaustive over all pairs of subsets of a universe of size n.
    for P in subsets(n):
        for Q in subsets(n):
            if prem(P, Q, n) and not concl(P, Q, n):
                return (sorted(P), sorted(Q))
    return None

